-- Упражнения книги 17, глава 20 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-domain-family', 0, 'func', 'Семейство домена', 'Тип домена хранилища определяет его семейство. Напишите функцию domain_family(domain_type): тип приходит строкой в любом регистре и, возможно, с пробелами по краям. Типы NFS, POSIXFS, GLUSTERFS и LOCALFS — семейство "file"; ISCSI и FCP — "block"; MANAGED_BLOCK — "managed"; любой другой тип (в том числе пустая строка) — "unknown".', 'def domain_family(domain_type):
    pass
', 'Приведите строку к верхнему регистру через strip().upper() и проверьте принадлежность множествам.', '{"func": "domain_family", "tests": [{"args": ["NFS"], "expected": "file"}, {"args": ["iscsi"], "expected": "block"}, {"args": [" FCP "], "expected": "block"}, {"args": ["glusterfs"], "expected": "file"}, {"args": ["LocalFS"], "expected": "file"}, {"args": ["managed_block"], "expected": "managed"}, {"args": ["ceph"], "expected": "unknown"}, {"args": [""], "expected": "unknown"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-file-paths', 1, 'func', 'Пути тома в файловом домене', 'В файловом домене том диска лежит по пути <mount>/<sd>/images/<img>/<vol>, его описание — в файле с суффиксом .meta, аренда — в файле с суффиксом .lease. Напишите функцию file_paths(mount, sd, img, vol): верните кортеж из трёх строк (путь тома, путь .meta, путь .lease). Точка монтирования mount может заканчиваться одним или несколькими слэшами — их нужно убрать, чтобы в путях не было двойных слэшей.', 'def file_paths(mount, sd, img, vol):
    pass
', 'mount.rstrip(''/'') и f-строка; суффиксы просто дописываются к пути тома.', '{"func": "file_paths", "tests": [{"args": ["/rhev/data-center/mnt/srv:_data", "sd1", "img1", "v1"], "expected": {"__tuple__": ["/rhev/data-center/mnt/srv:_data/sd1/images/img1/v1", "/rhev/data-center/mnt/srv:_data/sd1/images/img1/v1.meta", "/rhev/data-center/mnt/srv:_data/sd1/images/img1/v1.lease"]}}, {"args": ["/m/", "s", "i", "v"], "expected": {"__tuple__": ["/m/s/images/i/v", "/m/s/images/i/v.meta", "/m/s/images/i/v.lease"]}}, {"args": ["/m///", "s", "i", "v"], "expected": {"__tuple__": ["/m/s/images/i/v", "/m/s/images/i/v.meta", "/m/s/images/i/v.lease"]}}, {"args": ["/", "s", "i", "v"], "expected": {"__tuple__": ["/s/images/i/v", "/s/images/i/v.meta", "/s/images/i/v.lease"]}}, {"args": ["x", "a-b", "c-d", "e-f"], "expected": {"__tuple__": ["x/a-b/images/c-d/e-f", "x/a-b/images/c-d/e-f.meta", "x/a-b/images/c-d/e-f.lease"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-parse-meta', 2, 'func', 'Разбор метаданных домена', 'Файл dom_md/metadata состоит из строк КЛЮЧ=ЗНАЧЕНИЕ. Напишите функцию parse_domain_meta(text): верните словарь. Правила: из каждой строки сначала убираются пробелы по краям; пустые строки и строки без знака = пропускаются (например, строка EOF); строка делится по ПЕРВОМУ знаку =, поэтому значение может содержать = и быть пустым; ключ _SHA_CKSUM в словарь не попадает; значения ключей VERSION, MASTER_VERSION, LEASETIMESEC, LEASERETRIES, IOOPTIMEOUTSEC и LOCKRENEWALINTERVALSEC, если состоят только из цифр, превращаются в целые числа, остальные значения остаются строками. Если ключ повторяется, побеждает последняя строка.', 'def parse_domain_meta(text):
    pass
', 'splitlines(), затем line.split(''='', 1); целые — через str.isdigit().', '{"func": "parse_domain_meta", "tests": [{"args": ["CLASS=Data\nROLE=Master\nVERSION=5\nEOF\n"], "expected": {"CLASS": "Data", "ROLE": "Master", "VERSION": 5}}, {"args": ["REMOTE_PATH=srv:/export/a=b\nTYPE=NFS\n"], "expected": {"REMOTE_PATH": "srv:/export/a=b", "TYPE": "NFS"}}, {"args": ["DESCRIPTION=\nSDUUID=abc\n_SHA_CKSUM=1234abcd\nEOF"], "expected": {"DESCRIPTION": "", "SDUUID": "abc"}}, {"args": ["  LEASETIMESEC=60  \n\n  LEASERETRIES=3\nIOOPTIMEOUTSEC=ten\nLOCKRENEWALINTERVALSEC=5\n"], "expected": {"LEASETIMESEC": 60, "LEASERETRIES": 3, "IOOPTIMEOUTSEC": "ten", "LOCKRENEWALINTERVALSEC": 5}}, {"args": ["MASTER_VERSION=1\nMASTER_VERSION=2\nPOOL_UUID=p1\n"], "expected": {"MASTER_VERSION": 2, "POOL_UUID": "p1"}}, {"args": [""], "expected": {}}, {"args": ["EOF\njunk line\n"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-lv-tags', 3, 'func', 'Теги логического тома', 'В блочном домене связи тома записаны в тегах LVM. Напишите функцию parse_lv_tags(tags): tags — список строк. Тег IU_<x> задаёт образ (image) со значением x, тег PU_<x> задаёт родителя (parent), тег MD_<n> задаёт номер слота метаданных (slot) как целое число. Верните словарь с ключами "image", "parent", "slot"; отсутствующее значение — None. Родитель, равный нулевому идентификатору 00000000-0000-0000-0000-000000000000, означает, что родителя нет (база), и тоже даёт None. Остальные теги игнорируются. Если тег одного вида встретился несколько раз, побеждает последний.', 'def parse_lv_tags(tags):
    pass
', 'Для каждого тега проверяйте tag.startswith(''IU_'') и т. д.; срез tag[3:] даёт значение.', '{"func": "parse_lv_tags", "tests": [{"args": [["IU_img1", "PU_par1", "MD_7"]], "expected": {"image": "img1", "parent": "par1", "slot": 7}}, {"args": [[]], "expected": {"image": null, "parent": null, "slot": null}}, {"args": [["MD_12", "OTHER_tag", "IU_x"]], "expected": {"image": "x", "parent": null, "slot": 12}}, {"args": [["PU_00000000-0000-0000-0000-000000000000", "IU_i", "MD_0"]], "expected": {"image": "i", "parent": null, "slot": 0}}, {"args": [["IU_a", "IU_b", "MD_1", "MD_2"]], "expected": {"image": "b", "parent": null, "slot": 2}}, {"args": [["XIU_not", "pu_lower"]], "expected": {"image": null, "parent": null, "slot": null}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-chain-order', 4, 'func', 'Порядок томов в цепочке', 'Тома одного образа приходят в произвольном порядке как список кортежей (id, parent); у базы parent — пустая строка. Напишите функцию chain_order(volumes): верните список идентификаторов от базы к листу. Цепочка считается корректной, только если: идентификаторы не повторяются, база ровно одна, каждый parent (кроме пустого) есть среди идентификаторов, ни у какого тома нет двух детей, и все тома входят в одну цепочку от базы (циклы недостижимы от базы). Для любой некорректной цепочки и для пустого списка верните пустой список.', 'def chain_order(volumes):
    pass
', 'Постройте словарь parent → ребёнок; пока строите, ловите второго ребёнка. Пройдите от базы и сравните длину обхода с числом томов.', '{"func": "chain_order", "tests": [{"args": [[{"__tuple__": ["c", "b"]}, {"__tuple__": ["a", ""]}, {"__tuple__": ["b", "a"]}]], "expected": ["a", "b", "c"]}, {"args": [[{"__tuple__": ["only", ""]}]], "expected": ["only"]}, {"args": [[]], "expected": []}, {"args": [[{"__tuple__": ["a", ""]}, {"__tuple__": ["b", "a"]}, {"__tuple__": ["c", "a"]}]], "expected": []}, {"args": [[{"__tuple__": ["a", ""]}, {"__tuple__": ["x", ""]}]], "expected": []}, {"args": [[{"__tuple__": ["b", "zzz"]}, {"__tuple__": ["a", ""]}]], "expected": []}, {"args": [[{"__tuple__": ["a", ""]}, {"__tuple__": ["x", "y"]}, {"__tuple__": ["y", "x"]}]], "expected": []}, {"args": [[{"__tuple__": ["a", ""]}, {"__tuple__": ["a", ""]}]], "expected": []}, {"args": [[{"__tuple__": ["d", "c"]}, {"__tuple__": ["b", "a"]}, {"__tuple__": ["a", ""]}, {"__tuple__": ["c", "b"]}]], "expected": ["a", "b", "c", "d"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-read-lookup', 5, 'func', 'Откуда читается блок', 'Чтение в цепочке идёт от листа вниз к базе. Цепочка — список кортежей (id тома, список выделенных кластеров), порядок от базы к листу. Напишите функцию read_source(chain, cluster): верните кортеж (id, проверено), где id — самый верхний том, в котором кластер выделен, а проверено — сколько томов пришлось просмотреть, считая найденный. Если кластера нет ни в одном томе, он читается как нули: верните ("zero", число томов в цепочке). Для пустой цепочки верните ("zero", 0).', 'def read_source(chain, cluster):
    pass
', 'Идите по reversed(chain) со счётчиком; если цикл закончился без находки — это нули.', '{"func": "read_source", "tests": [{"args": [[{"__tuple__": ["base", [0, 1, 2]]}, {"__tuple__": ["snap", [1]]}, {"__tuple__": ["leaf", [2, 5]]}], 2], "expected": {"__tuple__": ["leaf", 1]}}, {"args": [[{"__tuple__": ["base", [0, 1, 2]]}, {"__tuple__": ["snap", [1]]}, {"__tuple__": ["leaf", [2, 5]]}], 1], "expected": {"__tuple__": ["snap", 2]}}, {"args": [[{"__tuple__": ["base", [0, 1, 2]]}, {"__tuple__": ["snap", [1]]}, {"__tuple__": ["leaf", [2, 5]]}], 0], "expected": {"__tuple__": ["base", 3]}}, {"args": [[{"__tuple__": ["base", [0, 1, 2]]}, {"__tuple__": ["snap", [1]]}, {"__tuple__": ["leaf", [2, 5]]}], 9], "expected": {"__tuple__": ["zero", 3]}}, {"args": [[], 0], "expected": {"__tuple__": ["zero", 0]}}, {"args": [[{"__tuple__": ["only", []]}], 3], "expected": {"__tuple__": ["zero", 1]}}, {"args": [[{"__tuple__": ["a", [4]]}, {"__tuple__": ["b", []]}, {"__tuple__": ["c", []]}, {"__tuple__": ["d", []]}], 4], "expected": {"__tuple__": ["a", 4]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-live-merge', 6, 'func', 'Слияние тома в родителя', 'Модель слияния звена цепочки. Цепочка — список кортежей (id, data) от базы к листу, где data — словарь кластер → содержимое (ключи-строки, значения-строки). Напишите функцию merge_volume(chain, vol): верните кортеж (новая_цепочка, перенесено). Правила: если vol — база (первый том) или такого тома нет, цепочка возвращается без изменений, перенесено равно 0. Иначе данные тома vol переносятся в его родителя (предыдущий том): для каждого кластера значение из vol заменяет значение родителя, остальные кластеры родителя остаются; том vol из цепочки удаляется, порядок остальных не меняется, тот, что стоял после vol, теперь следует за родителем. «перенесено» — число кластеров в data тома vol. Исходные списки и словари менять нельзя; новая цепочка состоит из кортежей (id, словарь).', 'def merge_volume(chain, vol):
    pass
', 'Найдите индекс i тома vol; объединённый словарь — {**chain[i-1][1], **chain[i][1]}; соберите новый список без i.', '{"func": "merge_volume", "tests": [{"args": [[{"__tuple__": ["base", {"c0": "a", "c1": "b"}]}, {"__tuple__": ["snap", {"c1": "B", "c2": "C"}]}, {"__tuple__": ["leaf", {"c2": "Z"}]}], "snap"], "expected": {"__tuple__": [[{"__tuple__": ["base", {"c0": "a", "c1": "B", "c2": "C"}]}, {"__tuple__": ["leaf", {"c2": "Z"}]}], 2]}}, {"args": [[{"__tuple__": ["base", {"c0": "a", "c1": "b"}]}, {"__tuple__": ["snap", {"c1": "B", "c2": "C"}]}, {"__tuple__": ["leaf", {"c2": "Z"}]}], "leaf"], "expected": {"__tuple__": [[{"__tuple__": ["base", {"c0": "a", "c1": "b"}]}, {"__tuple__": ["snap", {"c1": "B", "c2": "Z"}]}], 1]}}, {"args": [[{"__tuple__": ["base", {"c0": "a"}]}, {"__tuple__": ["leaf", {"c0": "x"}]}], "base"], "expected": {"__tuple__": [[{"__tuple__": ["base", {"c0": "a"}]}, {"__tuple__": ["leaf", {"c0": "x"}]}], 0]}}, {"args": [[{"__tuple__": ["base", {"c0": "a"}]}, {"__tuple__": ["leaf", {"c0": "x"}]}], "nope"], "expected": {"__tuple__": [[{"__tuple__": ["base", {"c0": "a"}]}, {"__tuple__": ["leaf", {"c0": "x"}]}], 0]}}, {"args": [[{"__tuple__": ["base", {"c0": "a"}]}, {"__tuple__": ["s1", {}]}, {"__tuple__": ["leaf", {"c1": "y"}]}], "s1"], "expected": {"__tuple__": [[{"__tuple__": ["base", {"c0": "a"}]}, {"__tuple__": ["leaf", {"c1": "y"}]}], 0]}}, {"args": [[{"__tuple__": ["b", {"k": "1"}]}, {"__tuple__": ["s1", {"k": "2"}]}, {"__tuple__": ["s2", {"k": "3"}]}, {"__tuple__": ["l", {}]}], "s2"], "expected": {"__tuple__": [[{"__tuple__": ["b", {"k": "1"}]}, {"__tuple__": ["s1", {"k": "3"}]}, {"__tuple__": ["l", {}]}], 1]}}, {"args": [[], "x"], "expected": {"__tuple__": [[], 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-thin-extend', 7, 'func', 'Расширение тонкого тома', 'Модель расширения тонкого qcow2-тома на блочном домене (все числа в МБ). Том имеет текущий размер size, максимум max_size, порция расширения chunk и порог threshold. Заданы замеры samples — заполнение образа (used) в моменты опроса. Для каждого замера по порядку: 1) если used больше size, машина получила ошибку записи — pauses увеличивается на 1, затем том экстренно расширяется порциями по chunk (но не больше max_size), пока size не станет не меньше used или не упрётся в max_size; каждая порция — одно расширение; 2) затем, если size меньше max_size и свободное место size − used строго меньше threshold, том расширяется ещё одной порцией (не больше max_size) — одно расширение. Напишите функцию thin_extend(size, chunk, threshold, max_size, samples): верните кортеж (итоговый_size, число_расширений, pauses).', 'def thin_extend(size, chunk, threshold, max_size, samples):
    pass
', 'Заведите три счётчика; шаг расширения — size = min(size + chunk, max_size). Условия 1 и 2 проверяются подряд для каждого замера.', '{"func": "thin_extend", "tests": [{"args": [1024, 1024, 512, 10240, []], "expected": {"__tuple__": [1024, 0, 0]}}, {"args": [1024, 1024, 512, 10240, [100, 400, 600]], "expected": {"__tuple__": [2048, 1, 0]}}, {"args": [1024, 1024, 512, 10240, [100, 500, 600, 1500, 2000]], "expected": {"__tuple__": [3072, 2, 0]}}, {"args": [1024, 1024, 512, 10240, [3000]], "expected": {"__tuple__": [4096, 3, 1]}}, {"args": [1024, 1024, 512, 2048, [900, 1900, 2000, 2048]], "expected": {"__tuple__": [2048, 1, 0]}}, {"args": [1024, 1024, 512, 10240, [1024]], "expected": {"__tuple__": [2048, 1, 0]}}, {"args": [1024, 512, 100, 4096, [1100, 1700, 5000]], "expected": {"__tuple__": [4096, 6, 3]}}, {"args": [2048, 1024, 0, 4096, [2048, 2049, 4096]], "expected": {"__tuple__": [4096, 2, 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-pick-spm', 8, 'func', 'Выбор SPM', 'Модель выбора Storage Pool Manager. Хосты — список словарей с полями name (строка), id (целое, номер хоста), prio (целое: чем больше, тем выше приоритет; значение -1 означает «никогда не быть SPM»), up (bool) и sees_master (bool, хост видит мастер-домен). Подходящий хост: up и sees_master, и prio не меньше нуля. Напишите функцию pick_spm(hosts, current): current — имя нынешнего SPM или пустая строка. Если current подходит, он остаётся SPM (вернуть current). Иначе верните имя подходящего хоста с наибольшим prio, а при равенстве — с наименьшим id. Если подходящих нет, верните пустую строку.', 'def pick_spm(hosts, current):
    pass
', 'Сначала отфильтруйте подходящих, потом проверьте current среди имён, потом min по ключу (-prio, id).', '{"func": "pick_spm", "tests": [{"args": [[{"name": "a", "id": 1, "prio": 5, "up": true, "sees_master": true}, {"name": "b", "id": 2, "prio": 7, "up": true, "sees_master": true}], ""], "expected": "b"}, {"args": [[{"name": "a", "id": 1, "prio": 5, "up": true, "sees_master": true}, {"name": "b", "id": 2, "prio": 7, "up": true, "sees_master": true}], "a"], "expected": "a"}, {"args": [[{"name": "a", "id": 1, "prio": 5, "up": false, "sees_master": true}, {"name": "b", "id": 2, "prio": 7, "up": true, "sees_master": true}], "a"], "expected": "b"}, {"args": [[{"name": "a", "id": 3, "prio": 5, "up": true, "sees_master": true}, {"name": "b", "id": 2, "prio": 5, "up": true, "sees_master": true}], ""], "expected": "b"}, {"args": [[{"name": "a", "id": 1, "prio": -1, "up": true, "sees_master": true}], ""], "expected": ""}, {"args": [[{"name": "a", "id": 1, "prio": 9, "up": true, "sees_master": false}, {"name": "b", "id": 2, "prio": 0, "up": true, "sees_master": true}], "a"], "expected": "b"}, {"args": [[], "a"], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-lease-sim', 9, 'func', 'Симуляция аренды sanlock', 'Модель одной аренды. Событие — кортеж (время, хост, действие), события идут в неубывающем порядке времени, timeout — срок жизни аренды. Состояние: владелец и момент истечения expires. Аренда свободна, если владельца нет или время события не меньше expires (истекла). Действия: "acquire" — если аренда свободна или владелец тот же хост, хост становится владельцем, expires = время + timeout, результат "ok"; иначе "busy". "renew" — если хост владелец и время меньше expires, то expires = время + timeout, результат "ok"; иначе "lost" (состояние не меняется). "release" — если хост владелец и время меньше expires, аренда освобождается, результат "ok"; иначе "noop". Напишите функцию lease_sim(events, timeout): верните кортеж (список результатов по событиям, владелец после последнего события). Владелец после последнего события — имя хоста, только если аренда ещё не истекла в момент последнего события (время меньше expires), иначе пустая строка. Для пустого списка событий верните ([], "").', 'def lease_sim(events, timeout):
    pass
', 'Храните owner и expires; в начале каждого события вычислите free = owner is None or t >= expires.', '{"func": "lease_sim", "tests": [{"args": [[], 80], "expected": {"__tuple__": [[], ""]}}, {"args": [[{"__tuple__": [0, "h1", "acquire"]}, {"__tuple__": [10, "h2", "acquire"]}], 80], "expected": {"__tuple__": [["ok", "busy"], "h1"]}}, {"args": [[{"__tuple__": [0, "h1", "acquire"]}, {"__tuple__": [80, "h2", "acquire"]}], 80], "expected": {"__tuple__": [["ok", "ok"], "h2"]}}, {"args": [[{"__tuple__": [0, "h1", "acquire"]}, {"__tuple__": [50, "h1", "renew"]}, {"__tuple__": [100, "h2", "acquire"]}, {"__tuple__": [130, "h2", "acquire"]}], 80], "expected": {"__tuple__": [["ok", "ok", "busy", "ok"], "h2"]}}, {"args": [[{"__tuple__": [0, "h1", "acquire"]}, {"__tuple__": [100, "h1", "renew"]}, {"__tuple__": [101, "h2", "acquire"]}], 80], "expected": {"__tuple__": [["ok", "lost", "ok"], "h2"]}}, {"args": [[{"__tuple__": [0, "h1", "acquire"]}, {"__tuple__": [20, "h1", "release"]}, {"__tuple__": [21, "h2", "acquire"]}], 80], "expected": {"__tuple__": [["ok", "ok", "ok"], "h2"]}}, {"args": [[{"__tuple__": [0, "h1", "release"]}, {"__tuple__": [1, "h1", "renew"]}], 80], "expected": {"__tuple__": [["noop", "lost"], ""]}}, {"args": [[{"__tuple__": [0, "h1", "acquire"]}, {"__tuple__": [30, "h2", "release"]}, {"__tuple__": [200, "h1", "release"]}], 60], "expected": {"__tuple__": [["ok", "noop", "noop"], ""]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-domain-status', 10, 'func', 'Состояние домена', 'Модель определения состояния домена. Напишите функцию domain_status(maintenance, busy, reports): maintenance и busy — bool, reports — список кортежей (состояние_хоста, valid) с отчётами хостов о домене, valid — bool. Учитываются только отчёты хостов в состоянии "Up". Правила по порядку: если maintenance — "Maintenance"; иначе если busy (выполняется операция) — "Locked"; иначе если учтённых отчётов нет — "Unknown"; иначе если хотя бы один учтённый отчёт valid — "Active"; иначе — "Inactive".', 'def domain_status(maintenance, busy, reports):
    pass
', 'Отфильтруйте отчёты по состоянию Up, затем проверьте условия в указанном порядке.', '{"func": "domain_status", "tests": [{"args": [false, false, [{"__tuple__": ["Up", true]}, {"__tuple__": ["Up", false]}]], "expected": "Active"}, {"args": [false, false, [{"__tuple__": ["Up", false]}, {"__tuple__": ["Up", false]}]], "expected": "Inactive"}, {"args": [false, false, []], "expected": "Unknown"}, {"args": [false, false, [{"__tuple__": ["NonResponsive", true]}, {"__tuple__": ["Maintenance", true]}]], "expected": "Unknown"}, {"args": [false, false, [{"__tuple__": ["NonResponsive", true]}, {"__tuple__": ["Up", false]}]], "expected": "Inactive"}, {"args": [false, true, [{"__tuple__": ["Up", true]}]], "expected": "Locked"}, {"args": [true, true, [{"__tuple__": ["Up", true]}]], "expected": "Maintenance"}, {"args": [true, false, []], "expected": "Maintenance"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-space-report', 11, 'func', 'Отчёт о месте в домене', 'Модель учёта места в домене. Напишите функцию space_report(total_gb, disks, warn_pct, crit_gb): total_gb — ёмкость домена (целое, больше нуля), disks — список кортежей (виртуальный_размер, фактический_размер) в ГБ, warn_pct — порог предупреждения в процентах, crit_gb — критический порог в ГБ. Верните кортеж (free, overcommit, state). free = total_gb минус сумма фактических размеров. overcommit = сумма виртуальных размеров, делённая на total_gb, округлённая до двух знаков (round). state: "critical", если free строго меньше crit_gb; иначе "warning", если free * 100 строго меньше warn_pct * total_gb; иначе "ok".', 'def space_report(total_gb, disks, warn_pct, crit_gb):
    pass
', 'Три суммы по одному проходу; сравнение с warn_pct делайте без деления, умножением, чтобы не было дробей.', '{"func": "space_report", "tests": [{"args": [1000, [], 10, 5], "expected": {"__tuple__": [1000, 0.0, "ok"]}}, {"args": [1000, [{"__tuple__": [500, 200]}, {"__tuple__": [500, 300]}], 10, 5], "expected": {"__tuple__": [500, 1.0, "ok"]}}, {"args": [1000, [{"__tuple__": [2000, 850]}], 10, 5], "expected": {"__tuple__": [150, 2.0, "ok"]}}, {"args": [1000, [{"__tuple__": [3000, 901]}], 10, 5], "expected": {"__tuple__": [99, 3.0, "warning"]}}, {"args": [1000, [{"__tuple__": [3000, 900]}], 10, 5], "expected": {"__tuple__": [100, 3.0, "ok"]}}, {"args": [100, [{"__tuple__": [100, 96]}], 10, 5], "expected": {"__tuple__": [4, 1.0, "critical"]}}, {"args": [100, [{"__tuple__": [100, 95]}], 10, 5], "expected": {"__tuple__": [5, 1.0, "warning"]}}, {"args": [300, [{"__tuple__": [100, 10]}, {"__tuple__": [50, 5]}, {"__tuple__": [70, 7]}], 20, 10], "expected": {"__tuple__": [278, 0.73, "ok"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-lv-sizes', 12, 'func', 'Размеры логических томов', 'Модель размеров LV на блочном домене (всё в МБ, размер LV кратен extent_mb: округляйте вверх). Напишите функцию lv_sizes(virtual_mb, kind, chunk_mb, extent_mb): верните кортеж (начальный_размер, максимальный_размер). Для kind == "preallocated" оба равны виртуальному размеру, округлённому вверх до кратного extent_mb. Для kind == "thin" (qcow2 растёт) максимум — это виртуальный размер плюс 10 процентов запаса на метаданные qcow2 (считайте в целых числах: ceil(virtual_mb * 11 / 10)), округлённый вверх до кратного extent_mb; начальный размер — chunk_mb, округлённый вверх до кратного extent_mb, но не больше максимума.', 'def lv_sizes(virtual_mb, kind, chunk_mb, extent_mb):
    pass
', 'Функция округления вверх: -(-x // e) * e. Для thin сначала посчитайте максимум.', '{"func": "lv_sizes", "tests": [{"args": [10240, "preallocated", 1024, 128], "expected": {"__tuple__": [10240, 10240]}}, {"args": [1000, "preallocated", 1024, 128], "expected": {"__tuple__": [1024, 1024]}}, {"args": [10240, "thin", 1024, 128], "expected": {"__tuple__": [1024, 11264]}}, {"args": [100, "thin", 1024, 128], "expected": {"__tuple__": [128, 128]}}, {"args": [1000, "thin", 1000, 128], "expected": {"__tuple__": [1024, 1152]}}, {"args": [51200, "thin", 2560, 128], "expected": {"__tuple__": [2560, 56320]}}, {"args": [1, "preallocated", 1, 128], "expected": {"__tuple__": [128, 128]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ov20-lsm-rollback', 13, 'func', 'Откат живой миграции хранилища', 'Живая миграция хранилища выполняет шаги по порядку: "snapshot", "create_target", "mirror", "pivot", "delete_source". Напишите функцию lsm_run(fail_at): fail_at — имя шага, на котором происходит сбой, или пустая строка, если сбоев нет. Верните кортеж (done, location, cleanup). done — список успешно выполненных шагов по порядку (шаг со сбоем в него не входит; без сбоя — все пять). location — "target", если шаг pivot успешно выполнен, иначе "source". cleanup — список действий отката по порядку: если сбой на mirror или pivot — сначала "abort_mirror"; затем, если сбой на create_target, mirror или pivot, — "remove_target"; если сбой на delete_source — единственное действие "retry_delete_source"; при сбое на snapshot и без сбоя cleanup пустой.', 'def lsm_run(fail_at):
    pass
', 'steps.index(fail_at) даёт число выполненных шагов; затем несколько if для отката.', '{"func": "lsm_run", "tests": [{"args": [""], "expected": {"__tuple__": [["snapshot", "create_target", "mirror", "pivot", "delete_source"], "target", []]}}, {"args": ["snapshot"], "expected": {"__tuple__": [[], "source", []]}}, {"args": ["create_target"], "expected": {"__tuple__": [["snapshot"], "source", ["remove_target"]]}}, {"args": ["mirror"], "expected": {"__tuple__": [["snapshot", "create_target"], "source", ["abort_mirror", "remove_target"]]}}, {"args": ["pivot"], "expected": {"__tuple__": [["snapshot", "create_target", "mirror"], "source", ["abort_mirror", "remove_target"]]}}, {"args": ["delete_source"], "expected": {"__tuple__": [["snapshot", "create_target", "mirror", "pivot"], "target", ["retry_delete_source"]]}}]}');
